    },
    [10] = {
      beijing = 3180,
      dialog = 3,
      music = "23_Lonely",
      renwu = "npc",
      sentence = "After all, everyone in the city knew that the royal family was declining year by year, and that Victor had been in a perennial coma ever since taking the throne, making him a mere puppet in the hands of the Secret Council.",
