      dialog = 3,
      music = "23_Lonely",
      renwu = "npc",
      sentence = "Recently, the capital city has been beleaguered with a rash of missing persons incidents, not a conducive atmosphere for festivities. And so after a bare-bones wedding ceremony, I was taken into the royal palace.",
