      sentence = "With that thought, the bitterness in my heart welled up higher and higher. I let out a sigh and decided to shake off this mood and talk about something more interesting.",
      next = {34}
    },
    [34] = {
      beijing = 3180,
      dialog = 3,
      music = "23_Lonely",
      renwu = "npc",
      sentence = "I meanderingly told happy, funny stories of bygone days, treating Victor as an obedient \"Sleeping Beauty doll\".",
