    [35] = {
      beijing = 3180,
      dhead = 112,
      dialog = 1,
      music = "23_Lonely",
      renming = "$u",
      renwu = "npc",
      sentence = "...As for fall, there's really not much fun to do. I've always found winter more amusing.",
      next = {36}
    },
