      dhead = 101,
      dialog = 1,
      music = "23_Lonely",
      renming = "$u",
      renwu = "npc",
      sentence = "When I was little, I loved nothing more than going out into the courtyard of the estate after a snow and building a snowman. I could build them up... this high. Look...",
