      renwu = "npc",
      role1 = 1162000,
      role2 = 101107,
      role3 = 101201,
      role6 = 11625007,
      roleanim = 1.2,
      ruchang = -1,
      sentence = "Of course Victor couldn't look, and he couldn't answer back either. Doing my best to stay chipper, I finished telling my stories. But there was nothing but endless emptiness.",
      next = {38}
    },
    [38] = {
      beijing = 3180,
