      role2 = 101107,
      role3 = 101201,
      role6 = 11625007,
      roleanim = 1.2,
      ruchang = 9,
      sentence = "I pulled a half-frown and mustered a bitter smile. Then, without consciously thinking about it, I reached out and poked at Victor's face, trying to make his expression match mine.",
      next = {39}
    },
    [39] = {
      beijing = 3180,
      dhead = 112,
      dialog = 1,
      music = "23_Lonely",
      renming = "$u",
      renwu = "npc",
