    },
    [27] = {
      beijing = 4786,
      dhead = 107,
      dialog = 1,
      music = "68_Valentine",
      renming = "$u",
      renwu = "npc",
      role1 = 3144000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "I've already been in your thrall for some time.",
      next = {28}
    },
    [28] = {
      beijing = 4786,
      dhead = 101,
      dialog = 1,
      music = "68_Valentine",
      renming = "$u",
      renwu = "npc",
      role1 = 3144000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "But you've always allowed me to be free, the same freedom I hope to give you.",
      next = {29}
    },
    [29] = {
      beijing = 4786,
      dialog = 3,
      music = "68_Valentine",
      renwu = "npc",
      sentence = "I didn't know if this was the answer Kiro wanted, but it came from the bottom of my heart.",
      next = {30}
    },
    [30] = {
      beijing = 4786,
      dialog = 3,
      music = "68_Valentine",
      renwu = "npc",
      sentence = "Love may bring the walls of our world closing in. It makes us control desires, keep our distance, and reject jumbled complexity.",
      next = {31}
    },
    [31] = {
      beijing = 4786,
      dialog = 3,
      music = "68_Valentine",
      renwu = "npc",
      sentence = "But it also gives us a glimpse into another universe. It makes the soul true and free. It lets us become our true selves.",
      next = {32}
    },
    [32] = {
      beijing = 4786,
      dialog = 3,
      music = "68_Valentine",
      renwu = "npc",
      sentence = "I saw Kiro let out a soft laugh, then he lifted me up in his arms.",
      next = {33}
    },
    [33] = {
      beijing = 4786,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "68_Valentine",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3144000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "What do you want to do?",
      voice = 2,
