      music = "68_Valentine",
      renwu = "npc",
      role1 = 3144000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "I stood up and took his hand, then pushed the locked door open with ease and looked back at him.",
