    },
    [36] = {
      beijing = 4786,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "68_Valentine",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3144000,
      role2 = 302108,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "How about a place where it's just the two of us?",
