      roleanim = 1.2,
      sentence = "Then let's go.",
      next = {38}
    },
    [38] = {
      beijing = 4786,
      dialog = 3,
      music = "pause",
      renwu = "npc",
      sentence = "I went with Kiro past flowers and sunshine into a deep part of the villa. Soon, I found myself looking at a somewhat run-down little concert hall.",
      next = {39}
    },
    [39] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "The chairs were all stacked upside-down on top of tables, and everything was covered in dust, as if no one had been here in a long time.",
      next = {40}
    },
    [40] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "There was only a flower-covered piano sitting in the middle of the raised stage. It was plunged in an ethereal light, like a whispered message left behind the scenes for a special audience member.",
      next = {41}
    },
    [41] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "Kiro stepped forward into the light, then turned his head and stared at me.",
      next = {42}
    },
    [42] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3144000,
      role2 = 302101,
      role3 = 302203,
      sentence = "I didn't give you any flowers just now, so I'll give you a song.",
      voice = 2,
      next = {43}
    },
    [43] = {
      beijing = 4787,
      dhead = 113,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 3144000,
