    },
    [44] = {
      beijing = 4787,
      bganim = 0,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "After hearing my answer, he first disappeared for a moment. When he reappeared beside the piano, he had on another outfit.",
      next = {45}
    },
    [45] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      sentence = "A dappled twinkling of reflected sunlight welled up in his eyes like the shimmering ocean, pouring straight into mine.",
      next = {46}
    },
    [46] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      sentence = "A deep and delicate melody flowed from Kiro's fingertips, bathing the world in silver light and glistening waves.",
      next = {47}
    },
    [47] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      sentence = "I looked up at him. The ethereal, pale light set him off in a silver halo, holy and beautiful.",
      next = {48}
    },
    [48] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      sentence = "Were we still in the performance now? I didn't know, and I didn't seem to care.",
