    },
    [49] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      sentence = "I saw only Kiro.",
      next = {50}
    },
    [50] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      sentence = "I saw his desire, his struggle, and his yearning.",
