    },
    [51] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "I walked silently up to him and sat down beside him.",
