    },
    [52] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302205,
      roleanim = 1.1,
