      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "And I just barged in a little impolitely.",
      next = {57}
    },
    [57] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302106,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "It was indeed impolite. Such a private place, and you came running in without even taking your shoes off.",
