    },
    [59] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.1,
      sentence = "Hearing Kiro's half-joking answer, I couldn't help but laugh. As I spoke, I bent over and undid one of the straps around my ankle.",
      next = {60}
    },
    [60] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302104,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "No need to redeem yourself. Next time, just run faster. Don't keep me waiting so long again.",
      voice = 2,
      next = {61}
    },
    [61] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "Before I had a chance to react, Kiro lifted me up onto the piano. My loosened shoe slipped off in the process, and I was left holding it.",
      next = {62}
    },
    [62] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "Without really thinking, I put a foot on his thigh, watching him as he lifted up his head in devotion.",
      next = {63}
    },
    [63] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302205,
      roleanim = 1.2,
      sentence = "The theme of this performance is \"freedom\".",
      voice = 2,
      next = {64}
    },
    [64] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "In an instant, a lot of things suddenly made sense. I stared at him for a moment, unable to resist teasing him.",
      next = {65}
    },
    [65] = {
      beijing = 4787,
      dhead = 107,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302203,
      roleanim = 1.2,
      sentence = "Hang on. You locked yourself up right after you met with me. What's that supposed to mean? I make you not free?",
      next = {66}
    },
    [66] = {
