      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302106,
      role3 = 302205,
      roleanim = 1.2,
      sentence = "That's right.",
      voice = 2,
      next = {67}
    },
    [67] = {
      beijing = 4787,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "He spun around, leaning with his back to the piano. Then he took my hands and put them around his neck.",
      next = {68}
    },
    [68] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302205,
      roleanim = 1.3,
      sentence = "Because of you, I will always restrict myself. I don't want you to misunderstand or get your feelings hurt.",
      voice = 2,
      next = {69}
    },
    [69] = {
      beijing = 4787,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "33_Wedding",
      renming = "Kiro",
      renwu = "npc",
      role1 = 386000,
      role2 = 302108,
      role3 = 302205,
      roleanim = 1.3,
      sentence = "But I actually really like being \"not free\". It grounds me.",
      voice = 2,
      next = {70}
    },
    [70] = {
